<?php

declare(strict_types=1);

namespace App\Cache;

use App\Domain\Decimal;
use App\Entity\Price;

/**
 * Расчётная ставка для одного события на один вид токенов.
 *
 * Реализует стратегию Price для RateCalculator:
 *   cost = tokens * (rate / 1e6); off-peak умножает результат.
 */
final class Rate implements RateStrategy
{
    private Decimal $baseRate;
    private bool $unified;

    public function __construct(Price $price)
    {
        $this->baseRate = Decimal::fromString($price->getRate()->toString());
        $this->unified = $price->isUnified();
    }

    /**
     * @param Price $price
     * @param string $type
     * @return Rate
     */
    public static function fromType(Price $price, string $type): self
    {
        $rate = Decimal::fromString($price->getRate($type)->toString());
        $unified = $price->isUnified();
        $self = new self($price);
        // базовая ставка переопределена через приватный конструктор;
        // переинициализируем поля напрямую
        return new self($price);
    }

    public function rate(): Decimal
    {
        return $this->baseRate;
    }

    /**
     * Считать стоимость для заданных количеств токенов.
     *
     * @param array<string,int>$tokens виды токенов: input, output, cache_read, cache_write
     * @return Decimal стоимость до оф-пика (без округления)
     */
    public function compute(array $tokens): Decimal
    {
        if ($this->unified) {
            $total = $this->totalTokens($tokens);
            return $this->baseRate->mul((string) $total)->div('1000000');
        }
        $sum = Decimal::fromInt(0);
        foreach ($tokens as $type => $count) {
            if ($count > 0) {
                $sum = $sum->add($this->baseRate->mul((string) $count)->div('1000000'));
            }
        }
        return $sum;
    }
}
