 * baseRate — ставка именно для этого вида; unified показывает, что
 * для разных видов токенов используется одна и та же ставка, поэтому
 * суммируются все виды, а не только запрошенный.
 *
 * cost = tokens * (rate / 1_000_000); off-peak умножает результат.
 */
final class Rate implements RateStrategy
{
    private Decimal $baseRate;
    private bool $unified;

    public function __construct(Price $price, string $type)
    {
        $this->baseRate = Decimal::fromString($price->getRate($type)->toString());
        $this->unified = $price->isUnified();
    }

    public function rate(): Decimal
    {
        return $this->baseRate;
    }

    /**
     * Считать стоимость для заданных количеств токенов.
     *
     * unified схема: cost = sum(all tokens) * rate / 1e6,
     * потому что для любого вида то применяем одну ставку.
     *
     * @param array<string,int>$tokens виды токенов: input, output, cache_read, cache_write
     * @return Decimal стоимость до оф-пика (без округления)
     */
    public function compute(array $tokens): Decimal
    {
        if ($this->unified) {
            $total = $this->totalTokens($tokens);
            return $this->baseRate->mul((string) $total)->div('1000000');
        }
        $tokens = array_keys($tokens);
        $sum = Decimal::fromInt(0);
        foreach ($tokens as $type) {
            $count = $tokens[$type];
            if ($count > 0) {
                $sum = $sum->add($this->baseRate->mul((string) $count)->div('1000000'));
            }
        }
        return $sum;
    }

    /**
     * @param array<string,int>$tokens
     */
    private function totalTokens(array $tokens): int
    {
        return array_sum($tokens);
    }
}
