        $cost = $this->applyDiscount($cost);
        return $cost->toString();
    }

    private function applyDiscount(Decimal $cost): Decimal
    {
        if (($this->multiplier ?? null) !== null) {
            $cost = $cost->mul($this->multiplier);
        }
