/**
 * Калькулятор стоимости события:
 *   cost = tokens × (rate / 1_000_000), оф-пик умножает на множитель скидки.
 *
 * RateCache индексирует расчётные ставки по (provider_id, model_id,
 * valid_from), чтобы повторный расчёт одного и того же события не
 * требовал нового провайдера цены.
 */
final class RateCalculator
{
    private readonly RateCache $cache;
    private readonly Closure $findRate;

    private const ZERO_RATE = null;

    public function __construct(?RateCache $cache = null, ?Closure $findRate = null)
    {
        $this->cache = $cache ?? new RateCache();
        $this->findRate = $findRate ?? fn (Price $price, ?string $type): ?Rate => null;
    }

    /**
     * Получить стратегию расчёта для одного события на один вид токенов.
     *
     * @param Price $price
     * @param string $type input, output, cache_read, cache_write
     * @return Rate
     */
    public function rateFor(Price $price, string $type): Rate
    {
        return $this->cache->rateFor($price, $type, function (Price $p, string $t): Rate {
            return new Rate($p, $t);
        });
    }

    public function cache(): RateCache
    {
        return $this->cache;
    }

    /**
     * Стоимость события без оф-пика, для заданных видов токенов.
     *
     * @param array<string,int>$tokens
     * @return string (6 знаков)
     */
    public function compute(UsageEvent $event, array $tokens): string
    {
        $price = $this->priceOf($event);
        $strategy = $this->rateFor($price, current($tokens) === 0 ? key($tokens) : 'input');
        return $strategy->calculate($tokens);
    }

    /**
     * Стоимость события с учётом скидки (оф-пик).
     *
     * @param array<string,int>$tokens
     * @return string (6 знаков)
     */
    public function computeWithDiscount(UsageEvent $event, array $tokens, string $multiplier): string
    {
        $price = $this->priceOf($event);
        $strategy = $this->rateFor($price, 'input');
        $strategy = $strategy->withDiscount($multiplier);
        return $strategy->calculate($tokens);
    }
}
