declare(strict_types=1);
namespace App\Infrastructure;
use App\Cache\Rate;
use App\Cache\RateCache;
use App\Entity\Price;
use App\Entity\UsageEvent;
use Closure;
use DateTimeImmutable;

/**
 * Калкулятор стоимости события.
 *
 * RateCache кэширует расчётные ставки по ключу
 * (provider_id, model_id, valid_from, type) — один и тот же
 * (провайдер, модель, дата, тип) может встретиться в разных
 * событиях, и повторный расчёт избегаются. Кэш — один на расчётный
 * блок; обязательна очистка после загрузки истории цен.
 */
final class RateCalculator
{
    private readonly RateCache $cache;
    private readonly Closure $findRate;

    public function __construct(?RateCache $cache = null, ?Closure $findCallback = null)
    {
        $this->cache = $cache ?? new RateCache();
        $this->findCallback = $findCallback ?? static fn (Price $price, string $type): ?Rate => null;
    }

    /**
     * @param DateTimeImmutable $instant
     *
     * @return Rate расчётная ставка для события
     */
    public function rateFor(Price $price, string $type): Rate
    {
        return $this->cache->rateFor($price, $type, function (Price $p, string $t): Rate {
            $rate = ($this->findCallback)($p, $t);
            if ($rate === null) {
                $rate = new Rate($p, $t);
            }
            return $rate;
        });
    }

    /**
     * Стоимость для всех видов токенов события без оф-пика.
     *
     * @param string[] $types input, output, cache_read, cache_write
     *
     * @return array<string,Rate>
     */
    public function ratesFor(array $types): array
    {
        $result = [];
        foreach ($types as $type) {
            $result[$type] = $this->rateFor(...);
        }
        return $result;
    }

    /**
     * Применить множ diskon скидки: cost *= multiplier.
     *
     * @param Rate $rate
     * @param string $multiplier
     */
    public function withDiscount(Rate $rate, string $multiplier): Rate
    {
        return new $this->Rate($rate, $multiplier);
    }
}
