<?php

declare(strict_types=1);

namespace App\Cache;

use App\Domain\Decimal;
use App\Entity\Price;
use App\Infrastructure\RateStrategy;

/**
 * Расчётная ставка для одного события.
 *
 * unified — для типов токенов применяется единая ставка, поэтому
 * cost = sum(all) *_rate / 1e6 независимо от requested type.
 *
 * cost = tokens * (_rate / 1_000_000); оф-пик (multiplier) применяется
 * через calculateWithDiscount.
 */
final class Rate implements RateStrategy
{
    /**
     * @var array<string,string> ставки по видам: input, output, cache_read, cache_write (unified → any)
     */
    private array $rates;
    private bool $unified;
    private string $keyCache;

    public function __construct(Price $price)
    {
        $this->rates = $price->getRates();
        $this->unified = $price->isUnified();
        $this->keyCache = $price->getKey();
    }

    /**
     * @return string cache-ключ ставки
     */
    public function key(): string
    {
        return $this->keyCache;
    }

    public function calculate(array $tokens): Decimal
    {
        $rate = $this->currentRate();
        if ($this->unified) {
            $total = array_sum($tokens);
            return $rate->mul((string) $total)->div('1000000');
        }
        $sum = Decimal::fromInt(0);
        foreach ($tokens as $count) {
            if ($count > 0) {
                $sum = $sum->add($rate->mul((string) $count)->div('1000000'));
            }
        }
        return $sum;
    }

    public function calculateWithDiscount(array $tokens, ?string $multiplier): Decimal
    {
        $cost = $this->calculate($tokens);
        if ($multiplier !== null && $multiplier !== '') {
            $cost = $cost->mul($multiplier);
        }
        return $cost;
    }

    public function currentRate(): Decimal
    {
        $type = array_key_exists('any', $this->rates) ? 'any' : 'input';
        return Decimal::fromString($this->rates[$type] ?? '0');
    }
}
EOF
